from pathlib import Path
import urllib.request,json,hashlib,datetime
p=Path(__file__).parent
urls={'drken_LICENSE.txt':'https://raw.githubusercontent.com/drken1215/algorithm/master/LICENSE','drken_miller_rabin.cpp':'https://raw.githubusercontent.com/drken1215/algorithm/master/MathNumberTheory/is_prime_Miller_Rabin.cpp','sprp_records.html':'https://miller-rabin.appspot.com/','jaeschke.pdf':'https://www.ams.org/journals/mcom/1993-61-204/S0025-5718-1993-1192971-8/S0025-5718-1993-1192971-8.pdf'}
rows=[]
for name,url in urls.items():
 row={'file':name,'url':url,'retrieved_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  with urllib.request.urlopen(url,timeout=30)as response:data=response.read();row.update(status=response.status,final_url=response.url)
  (p/name).write_bytes(data);row.update(bytes=len(data),sha256=hashlib.sha256(data).hexdigest())
 except Exception as e:row.update(error=str(e))
 rows.append(row)
(p/'sources.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n');print(json.dumps(rows,ensure_ascii=False))

